class Solution:
    def maximumLength(self, s: str) -> int:
        max_len = -1

        # Check for each character in the alphabet
        for c in set(s):
            # Create the continuous repeated substrings of character 'c'
            parts = s.split(c)
            count = 0
            max_current_len = 0

            for idx, part in enumerate(parts):
                if idx == 0:
                    current_len = len(part)
                elif count < 3:
                    current_len += len(part)
                    count += 1
                    if count == 3:
                        max_current_len = max(max_current_len, current_len)
                        count = 0
                        current_len = 0
                    else:
                        current_len += 1  # add the length of 'c' character itself
                else:
                    current_len += (len(part) + 1)  # continue with the next sequence

            # We compare with max_len to store the longest valid special substring length
            max_len = max(max_len, max_current_len)

        return max_len
